import React, { useState, useRef } from 'react';
import { CATEGORIES } from './constants';

const TEMPLATE_CSV = `name,company,size,category,unit,barcode,price,cost,stock,minStock
The Great Gatsby,Scribner,Paperback,Books,ea,9780743273565,14.99,7.00,12,3
White Rice 5kg,SunRice,5kg,Groceries,bag,,12.50,7.00,20,5
A4 Paper Ream,Reflex,500 sheets,Supplies,ream,,9.99,5.50,8,3`;

export default function BulkImport({ onAdd, onClose }) {
  const [rows,    setRows]    = useState([]);
  const [errors,  setErrors]  = useState([]);
  const [importing, setImporting] = useState(false);
  const [done,    setDone]    = useState(0);
  const fileRef = useRef(null);

  const downloadTemplate = () => {
    const a = document.createElement('a');
    a.href = 'data:text/csv;charset=utf-8,' + encodeURIComponent(TEMPLATE_CSV);
    a.download = 'unity_bookshop_import_template.csv';
    a.click();
  };

  const parseCSV = text => {
    const lines = text.trim().split('\n').map(l => l.replace(/\r/g,''));
    const headers = lines[0].split(',').map(h => h.trim().toLowerCase());
    return lines.slice(1).map((line, i) => {
      // Handle quoted fields
      const vals = [];
      let cur = '', inQ = false;
      for (const ch of line) {
        if (ch === '"') { inQ = !inQ; }
        else if (ch === ',' && !inQ) { vals.push(cur.trim()); cur = ''; }
        else cur += ch;
      }
      vals.push(cur.trim());
      const obj = {};
      headers.forEach((h, idx) => { obj[h] = vals[idx] || ''; });
      return { _row: i + 2, ...obj };
    });
  };

  const validate = rows => {
    const errs = [];
    const cats = Object.keys(CATEGORIES);
    rows.forEach(r => {
      if (!r.name) errs.push(`Row ${r._row}: name is required`);
      if (!r.price || isNaN(+r.price)) errs.push(`Row ${r._row}: price must be a number`);
      if (!r.stock || isNaN(+r.stock)) errs.push(`Row ${r._row}: stock must be a number`);
      if (r.category && !cats.includes(r.category)) errs.push(`Row ${r._row}: category must be one of: ${cats.join(', ')}`);
    });
    return errs;
  };

  const handleFile = e => {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = ev => {
      const parsed = parseCSV(ev.target.result);
      const errs = validate(parsed);
      setErrors(errs);
      setRows(parsed);
    };
    reader.readAsText(file);
  };

  const handleImport = async () => {
    if (errors.length) return;
    setImporting(true);
    let count = 0;
    for (const r of rows) {
      await onAdd({
        name:     r.name,
        company:  r.company || '',
        size:     r.size    || '',
        category: r.category || 'Other',
        unit:     r.unit    || 'ea',
        barcode:  r.barcode || '',
        price:    +r.price  || 0,
        cost:     +r.cost   || 0,
        stock:    +r.stock  || 0,
        minStock: +r.minstock || 3,
      });
      count++;
      setDone(count);
    }
    setImporting(false);
  };

  return (
    <div className="bs-modal" style={{maxWidth:'620px'}}>
      <div className="bs-mhdr">
        <h3>📂 Bulk Import Products</h3>
        <button className="bs-mx" onClick={onClose}>✕</button>
      </div>
      <div className="bs-form">

        {done > 0 && done === rows.length ? (
          <div style={{textAlign:'center', padding:'24px'}}>
            <div style={{fontSize:'40px',marginBottom:'12px'}}>✅</div>
            <h3 style={{marginBottom:'8px'}}>Import complete!</h3>
            <p className="bs-muted">{done} products added to inventory.</p>
            <button className="bs-pri" style={{marginTop:'16px'}} onClick={onClose}>Done</button>
          </div>
        ) : (
          <>
            {/* Step 1 — template */}
            <div className="bs-import-step">
              <span className="bs-import-num">1</span>
              <div style={{flex:1}}>
                <p style={{fontSize:'13px',fontWeight:600,color:'#f0f4ff',marginBottom:'4px'}}>Download the CSV template</p>
                <p className="bs-muted" style={{fontSize:'12px',marginBottom:'8px'}}>Fill in your products using this template. Required columns: name, price, stock.</p>
                <button type="button" className="bs-sec" onClick={downloadTemplate}>⬇ Download Template</button>
              </div>
            </div>

            {/* Step 2 — upload */}
            <div className="bs-import-step">
              <span className="bs-import-num">2</span>
              <div style={{flex:1}}>
                <p style={{fontSize:'13px',fontWeight:600,color:'#f0f4ff',marginBottom:'4px'}}>Upload your filled CSV file</p>
                <input ref={fileRef} type="file" accept=".csv" onChange={handleFile}
                  style={{display:'none'}} />
                <button type="button" className="bs-sec" onClick={()=>fileRef.current.click()}>📁 Choose CSV File</button>
                {rows.length > 0 && (
                  <span style={{marginLeft:'10px',fontSize:'12px',color:'#34d399'}}>{rows.length} rows loaded</span>
                )}
              </div>
            </div>

            {/* Errors */}
            {errors.length > 0 && (
              <div className="bs-import-errors">
                <p style={{fontWeight:600,marginBottom:'6px',color:'#f87171'}}>⚠ Fix these errors before importing:</p>
                {errors.map((e,i) => <p key={i} style={{fontSize:'12px',color:'#f87171',marginBottom:'2px'}}>• {e}</p>)}
              </div>
            )}

            {/* Preview table */}
            {rows.length > 0 && errors.length === 0 && (
              <div>
                <p style={{fontSize:'12px',color:'#64748b',marginBottom:'8px'}}>Preview ({rows.length} products):</p>
                <div style={{overflowX:'auto',maxHeight:'200px',overflowY:'auto',border:'1px solid #2a3a5c',borderRadius:'8px'}}>
                  <table className="bs-tbl">
                    <thead><tr><th>Name</th><th>Company</th><th>Size</th><th>Category</th><th>Price</th><th>Stock</th></tr></thead>
                    <tbody>
                      {rows.map((r,i)=>(
                        <tr key={i}>
                          <td>{r.name}</td>
                          <td className="bs-muted">{r.company||'—'}</td>
                          <td className="bs-muted">{r.size||'—'}</td>
                          <td className="bs-muted">{r.category||'Other'}</td>
                          <td>${(+r.price||0).toFixed(2)}</td>
                          <td>{r.stock}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

            {/* Import progress */}
            {importing && (
              <div className="bs-import-progress">
                <div className="bs-import-bar" style={{width:`${(done/rows.length)*100}%`}} />
                <p className="bs-muted" style={{fontSize:'12px',marginTop:'6px'}}>Importing {done}/{rows.length}…</p>
              </div>
            )}

            <div className="bs-fa">
              <button type="button" className="bs-sec" onClick={onClose}>Cancel</button>
              <button type="button" className="bs-pri"
                disabled={rows.length === 0 || errors.length > 0 || importing}
                onClick={handleImport}>
                {importing ? 'Importing…' : `✅ Import ${rows.length} Products`}
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}
